    Class<?> boxed(Class<?> c){return c==int.class?Integer.class:c==long.class?Long.class:c==boolean.class?Boolean.class:c==double.class?Double.class:c;}
    Object call(Object o,String n,Object...args)throws Exception{Class<?> type=o instanceof Class<?> c?c:o.getClass();List<Method> methods=new ArrayList<>(Arrays.asList(type.getMethods()));for(Class<?> c=type;c!=null;c=c.getSuperclass())methods.addAll(Arrays.asList(c.getDeclaredMethods()));for(Method m:methods)if(m.getName().equals(n)&&m.getParameterCount()==args.length){boolean ok=true;for(int i=0;i<args.length;i++)if(args[i]!=null&&!boxed(m.getParameterTypes()[i]).isInstance(args[i]))ok=false;if(ok){m.setAccessible(true);try{return m.invoke(o instanceof Class?null:o,args);}catch(InvocationTargetException ex){throw new RuntimeException(n,ex.getCause());}}}throw new NoSuchMethodException(type+" "+n);}
